// Junta la transacción, su recibo y el último bloque, y arma un resumen que se lee de un vistazo.
const hash = String($('Tu hash').first().json.hash || '').trim();
const tx = $('Leer la transacción').first().json;
const recibo = $('Leer el recibo').first().json;
const ultimo = $('Leer el último bloque').first().json;
const explorador = `https://build.avax.network/explorer/fuji/c-chain/tx/${hash}`;

// Pasa un entero en wei a texto, sin redondear. decimales: 18 para AVAX, 9 para nAVAX.
function enUnidad(wei, decimales = 18) {
  const base = 10n ** BigInt(decimales);
  const resto = (wei % base).toString().padStart(decimales, '0').replace(/0+$/, '');
  return resto ? `${wei / base}.${resto}` : `${wei / base}`;
}

// Si el hash está mal escrito, el RPC no devuelve «result» sino «error».
for (const r of [tx, recibo, ultimo]) {
  if (r.error) {
    return [{ json: { encontrada: false, hash, mensaje: `El RPC respondió un error: ${r.error.message ?? JSON.stringify(r.error)}. Un hash tiene 66 caracteres: 0x y 64 más.` } }];
  }
}

const t = tx.result;
if (!t) {
  return [{ json: { encontrada: false, hash, mensaje: 'No hay ninguna transacción con ese hash en Fuji. Revisá que esté completo y que sea de Fuji, no de la red principal.' } }];
}

const r = recibo.result; // null mientras la transacción espera entrar en un bloque
const valor = BigInt(t.value);
const enBloque = Boolean(r && t.blockNumber);
const bloque = enBloque ? BigInt(t.blockNumber) : null;
const gasUsado = enBloque ? BigInt(r.gasUsed) : null;
// effectiveGasPrice es lo que se pagó de verdad por cada unidad de gas.
const precio = BigInt((enBloque && r.effectiveGasPrice) || t.gasPrice);
const costo = enBloque ? gasUsado * precio : null;
// Confirmaciones: cuántos bloques hay desde el de la transacción (incluido) hasta el último.
// Si ya está en un bloque, tiene por lo menos 1: el RPC público reparte los pedidos entre varios
// servidores y el «último bloque» a veces llega uno atrasado.
let confirmaciones = 0n;
if (bloque !== null) {
  confirmaciones = BigInt(ultimo.result) - bloque + 1n;
  if (confirmaciones < 1n) confirmaciones = 1n;
}

let tipo = 'transferencia de AVAX';
if (!t.to) tipo = 'creación de un contrato';
else if (t.input && t.input !== '0x') tipo = 'llamada a un contrato';

return [
  {
    json: {
      encontrada: true,
      hash,
      estado: !enBloque ? 'pendiente' : r.status === '0x1' ? 'exitosa' : 'fallida',
      tipo,
      de: t.from,
      para: t.to ?? r?.contractAddress ?? null,
      montoAVAX: enUnidad(valor),
      montoWei: valor.toString(),
      gasUsado: gasUsado === null ? null : Number(gasUsado),
      precioGas: { wei: precio.toString(), nAVAX: enUnidad(precio, 9) },
      costoAVAX: costo === null ? null : enUnidad(costo),
      costoWei: costo === null ? null : costo.toString(),
      bloque: bloque === null ? null : Number(bloque),
      confirmaciones: Number(confirmaciones),
      eventos: enBloque ? r.logs.length : 0,
      explorador,
    },
  },
];
